/** La clase de monstruo de `claseDeMonstruoApi` con los especiales de cada nivel que da la API. */
export function claseDeMonstruoConEspecialesApi(tabla: TablaClaseDeMonstruo): Record<string, any> {
    const clase = claseDeMonstruoApi(tabla);
    const especiales = ESPECIALES_POR_NIVEL_API[tabla.nombre] ?? {};
    clase['Desglose_niveles'].forEach((nivel: any) => nivel.Especiales = JSON.parse(JSON.stringify(especiales[`${nivel.Nivel}`] ?? [])));
    return clase;
}

