/** La tabla de la clase con los ids de `rol_dev` (la clase y su raza mutada), para que la raza real sea su mutación. */
export function conIdsDeRolDev(tabla: TablaClaseDeMonstruo, idClase: number, idRaza: number): TablaClaseDeMonstruo {
    return { ...tabla, id: idClase, mutacion: { Id: idRaza, Nombre: tabla.mutacion.Nombre } };
}
